package it.frociart.app;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.Consumer;import static it.frociart.app.FlowModel.*;
public class ForLoopTests {
 static int checks;static Path root;
 static void eq(Object a,Object b,String label){checks++;if(!Objects.equals(a,b))throw new AssertionError(label+": expected "+a+" actual "+b);}
 static String read(Path p)throws Exception{return new String(Files.readAllBytes(p),StandardCharsets.UTF_8);}
 static FlowEngine.Runner run(Document d,String inputs){FlowEngine.Runner r=new FlowEngine.Runner(d);String[] values=inputs.split("\\|",-1);int used=0;for(int t=0;t<11000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;t++){if(r.state==FlowEngine.State.WAITING){eq(false,r.step(),"wait stable");eq(true,r.submitInput(values[used++]),"input");}else if(r.state==FlowEngine.State.WAITING_FILE){eq(false,r.step(),"file wait stable");String data=values[used++];eq(true,data.startsWith("F:"),"file fixture");eq(true,r.provideFile(r.pendingFile(),data.substring(2)),"file accepted");}else r.step();}eq(inputs.isEmpty()?0:values.length,used,"input requests exactly once");return r;}
 static void valid(Document d,String inputs,String expected,String name){FlowEngine.Runner r=run(d,inputs);eq(FlowEngine.State.COMPLETED,r.state,name+" completes "+r.errorMessage);eq(expected,String.join("|",r.output),name+" output");}
 static Node find(Document d,int kind,String text){for(Node n:d.nodes)if(n.kind==kind&&(text==null||n.text.contains(text)))return n;throw new AssertionError("missing node");}
 static void mutant(Consumer<Document> edit,String expected){Document d=FlowPseudocode.decode("p=2\nPER i DA 1 A 5 PASSO p FAI\nSTAMPA i\nFINE PER");edit.accept(d);String code=FlowPseudocode.encode(d);eq(false,code.contains("PER i DA"),"edited pattern not hidden");FlowEngine.Runner original=run(d,""),back=run(FlowPseudocode.decode(code),"");eq(original.state,back.state,"edited state");eq(String.join("|",original.output),String.join("|",back.output),"edited behavior");if(expected!=null)eq(expected,String.join("|",back.output),"edited oracle");}
 static void fuzz(){Random random=new Random(8723);for(int trial=0;trial<160;trial++){Document d=FlowPseudocode.decode("p=2\nPER i DA 1 A 5 PASSO p FAI\nSE i=3 ALLORA\nSTAMPA i*2\nALTRIMENTI\nSTAMPA i\nFINE SE\nFINE PER\nSTAMPA \"fine\"");int kind=trial%4;if(kind==0){Edge edge=d.edges.get(random.nextInt(d.edges.size()));edge.to=d.nodes.get(1+random.nextInt(d.nodes.size()-1)).id;}else if(kind==1){d.edges.remove(random.nextInt(d.edges.size()));}else if(kind==2){find(d,OUTPUT,null).text=random.nextBoolean()?"limite_ciclo_1":"passo_ciclo_1";}else find(d,PROCESS," = int(").text+="; z=3";String before=FlowCodec.encode(d),code=FlowPseudocode.encode(d);Document back=FlowPseudocode.decode(code);FlowEngine.Runner a=run(d,""),b=run(back,"");eq(a.state,b.state,"mutated graph state "+trial);eq(String.join("|",a.output),String.join("|",b.output),"mutated graph output "+trial);eq(d.nodes.size(),back.nodes.size(),"mutated nodes "+trial);eq(d.edges.size(),back.edges.size(),"mutated edges "+trial);eq(before,FlowCodec.encode(d),"mutated export nonmutating "+trial);}}
 public static void main(String[] args)throws Exception{root=Paths.get(args[0]);Files.createDirectories(root.resolve("java-docs"));List<Path> files=new ArrayList<>();try(DirectoryStream<Path> ds=Files.newDirectoryStream(root.resolve("fixtures"),"*.pseudo")){for(Path p:ds)files.add(p);}Collections.sort(files);for(Path file:files){String name=file.getFileName().toString().replace(".pseudo",""),expected=read(file.resolveSibling(name+".expected")),input=read(file.resolveSibling(name+".inputs"));Document d=FlowPseudocode.decode(read(file));String before=FlowCodec.encode(d),code=FlowPseudocode.encode(d);eq(true,code.contains("PER i DA"),name+" readable FOR");eq(before,FlowCodec.encode(d),name+" nonmutating export");valid(d,input,expected,name);valid(FlowPseudocode.decode(code),input,expected,name+" text roundtrip");valid(FlowCodec.decode(before),input,expected,name+" project roundtrip");Files.write(root.resolve("java-docs").resolve(name+".frociart"),before.getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("java-docs").resolve(name+".txt"),code.getBytes(StandardCharsets.UTF_8));Path other=root.resolve("pc-docs").resolve(name+".frociart");if(Files.exists(other)){valid(FlowCodec.decode(read(other)),input,expected,name+" Windows file");eq(code,read(other.resolveSibling(name+".txt")),name+" platform text");}}
 for(String value:new String[]{"0","1.5","2147483648","-2147483649","vero","\"2\"","[2]"}){FlowEngine.Runner r=run(FlowPseudocode.decode("p="+value+"\ni=91\nPER i DA 1 A 3 PASSO p FAI\nSTAMPA i\nFINE PER"),"");eq(FlowEngine.State.ERROR,r.state,"invalid dynamic step "+value);eq(0,r.output.size(),"no invalid iteration");eq("91",r.variables.get("i").format(),"failed init atomic");eq(true,r.errorMessage.toLowerCase(Locale.ROOT).contains("passo"),"step-specific error");}
 for(String value:new String[]{"0","1.5","2147483648"}){boolean failed=false;try{FlowPseudocode.decode("PER i DA 1 A 3 PASSO "+value+" FAI\nFINE PER");}catch(IllegalArgumentException ex){failed=true;}eq(true,failed,"invalid constant rejected");}
 mutant(d->find(d,DECISION,null).text="i < limite_ciclo_1","1|3");
 mutant(d->find(d,PROCESS,"i = i +").text="i = i + 1","1|2|3|4|5");
 mutant(d->find(d,OUTPUT,null).text="limite_ciclo_1","5|5|5");
 mutant(d->find(d,PROCESS," = int(").text+="; altra = 7","1|3|5");
 fuzz();
 System.out.println("FOR_LOOP PASS checks="+checks);
 }
}
